const find=()=>[...document.querySelectorAll('*')].find(e=>e.children.length==0&&e.textContent.includes('HAK-5638'));
let sc=[...document.querySelectorAll('*')].find(e=>e.scrollHeight>e.clientHeight+50&&getComputedStyle(e).overflowY!='visible')||document.scrollingElement;
let r=null;
for(let i=0;i<500&&!r;i++){r=find();if(r)break;sc.scrollTop+=200;await new Promise(x=>setTimeout(x,50));}
if(r){r.scrollIntoView({block:'center'});}
r? r.closest('li,tr,div[class*=row],div[class*=item]')?.outerHTML.slice(0,500):'notfound '+sc.scrollTop

